using ICSharpCode.AvalonEdit.Highlighting;
static class UiChecks {
 [StructLayout(LayoutKind.Sequential)]struct NativePoint{public int X,Y;}
 [StructLayout(LayoutKind.Sequential)]struct MouseInput{public int X,Y;public uint Data,Flags,Time;public UIntPtr ExtraInfo;}
 [StructLayout(LayoutKind.Sequential)]struct NativeInput{public uint Type;public MouseInput Mouse;}
 [DllImport("user32.dll")]static extern bool GetCursorPos(out NativePoint point);
 [DllImport("user32.dll")]static extern bool SetCursorPos(int x,int y);
 [DllImport("user32.dll")]static extern uint SendInput(uint count,NativeInput[] inputs,int size);
 [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr handle);
 static T Field<T>(object obj,string name){return (T)obj.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(obj);}
 static Rect Bounds(FrameworkElement e,FrameworkElement root){return e.TransformToAncestor(root).TransformBounds(new Rect(new Point(),e.RenderSize));}
 static void Mouse(uint flag){if(SendInput(1,new[]{new NativeInput{Mouse=new MouseInput{Flags=flag}}},Marshal.SizeOf(typeof(NativeInput)))!=1)throw new Exception("Mouse input failed");}
 static void Move(EditorInput input,Point p){Point screen=input.PointToScreen(p);SetCursorPos((int)Math.Round(screen.X),(int)Math.Round(screen.Y));}
 static Point CharacterPoint(EditorInput input,int i){Rect a=input.CharacterRect(i),b=input.CharacterRect(i+1);if(b.X<=a.X)throw new Exception("No glyph geometry "+i);return new Point(a.X+(b.X-a.X)*.2,a.Y+a.Height/2);}
 public static void Run(Application app,string path){string folder=Path.GetDirectoryName(Path.GetFullPath(path));Engine.DataRoot=Path.Combine(folder,"ui-state-"+Guid.NewGuid().ToString("N"));var log=new List<string>();Action<bool,string> check=(ok,label)=>{log.Add((ok?"PASS ":"FAIL ")+label);File.WriteAllLines(path,log.ToArray());if(!ok)throw new Exception(label);};var main=new MainWindow(true);main.ContentRendered+=async(s,e)=>{try{await Verify(main,folder,check);log.Add("ALL UI CHECKS PASSED");File.WriteAllLines(path,log.ToArray());main.Close();}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(path,log.ToArray());app.Shutdown(1);}};app.Run(main);}
 static async Task Verify(MainWindow main,string folder,Action<bool,string> check){main.PreviewSize(1400,900);await Task.Delay(200);var root=(FrameworkElement)main.Content;var editor=Field<CodeEditor>(main,"editor");var input=editor.Input;
  check(Bank.All().Count==90&&Bank.All().Last().Category.Contains("项目"),"90 questions ending with project exams");check(Bounds(editor,root).Width>650&&Bounds(editor,root).Height>300,"Large code workspace alongside results");check(Field<TextBox>(main,"outputDetail").ActualWidth>200,"Right-side results panel is visible");
  var answer=new AnswerWindow(Bank.All()[0]){Owner=main};answer.Show();await Task.Delay(60);check(answer.AnswerEditor.Visibility==Visibility.Collapsed&&!answer.ImportButton.IsEnabled,"Answers begin with hint only");answer.Reveal.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(answer.AnswerEditor.Visibility==Visibility.Visible&&answer.ImportButton.IsEnabled,"Reveal enables code and import");answer.ImportButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(answer.ImportAnswer,"One-click answer import requested");
  main.GetType().GetField("preview",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(main,false);editor.Text="// original draft\nint main(void){return 0;}";main.ImportReference();check(editor.Text==Bank.All()[0].Reference,"Import replaces editor with exact reference answer");check(File.ReadAllText(Directory.GetFiles(Path.Combine(Engine.DataRoot,"answer-import-backups")).Single())=="// original draft\nint main(void){return 0;}","Original draft is backed up before importing answer");check(File.ReadAllText(Path.Combine(Engine.DataRoot,"drafts","01.c"))==editor.Text,"Imported answer is saved as current draft");
  NativePoint saved;GetCursorPos(out saved);IntPtr foreground=GetForegroundWindow();bool topmost=main.Topmost;int hits=0,clicks=0,drags=0;
  try{main.Topmost=true;main.Activate();string[] lines=Enumerable.Range(0,70).Select(i=>"    int value_"+i.ToString("000")+" = "+i+"; // 中文注释\tend();"+(i%5==0?new string('x',160):"")).ToArray();
   foreach(double scale in new[]{1.0,1.5,2.0})foreach(int size in new[]{14,16,18,20,22,24}){
    editor.LayoutTransform=new ScaleTransform(scale,scale);editor.SetFontSize(size);editor.Text=string.Join("\n",lines);input.ScrollToHome();main.UpdateLayout();await Task.Delay(70);input.TextArea.TextView.EnsureVisualLines();int target=input.Document.GetLineByNumber(3).Offset+9;input.Focus();input.Select(0,0);Point p=CharacterPoint(input,target);Move(input,p);Mouse(2);Mouse(4);await Task.Delay(50);check(input.CaretOffset==target,"Actual mouse click aligns at font "+size+" / scale "+scale+" ("+input.CaretOffset+" vs "+target+")");clicks++;
    foreach(var visual in input.TextArea.TextView.VisualLines.Take(6)){int start=visual.FirstDocumentLine.Offset;foreach(int off in new[]{0,4,9,16,24,26,27,28,29,30,33}){int idx=start+off;Point pt=CharacterPoint(input,idx);if(pt.X<0||pt.X>=input.ActualWidth||pt.Y<0||pt.Y>=input.ActualHeight)continue;Point screen=input.PointToScreen(pt);Point round=input.PointFromScreen(new Point(Math.Round(screen.X),Math.Round(screen.Y)));if(input.Hit(round)!=idx)throw new Exception("Hit mismatch size="+size+" scale="+scale+" index="+idx+" hit="+input.Hit(round));hits++;}}
    int from=input.Document.GetLineByNumber(1).Offset+4,to=input.Document.GetLineByNumber(3).Offset+16;Move(input,CharacterPoint(input,from));Mouse(2);await Task.Delay(40);Move(input,CharacterPoint(input,to));await Task.Delay(50);Mouse(4);await Task.Delay(40);check(input.SelectionStart==from&&input.SelectionLength==to-from,"Actual multiline drag aligns at "+size+" / "+scale);drags++;
    string original=input.Text;input.Select(target,0);input.SelectedText="TEST";check(input.Text==original.Insert(target,"TEST"),"Insert offset remains exact");input.Undo();check(input.Text==original,"Undo unaffected by highlighting");input.Select(from,to-from);input.SelectedText="REPLACED";check(input.Text==original.Remove(from,to-from).Insert(from,"REPLACED"),"Multiline replacement is exact");input.Undo();check(input.Text==original,"Replacement undo is exact");
    input.ScrollToLine(45);input.ScrollToHorizontalOffset(90);await Task.Delay(50);input.TextArea.TextView.EnsureVisualLines();var line=input.TextArea.TextView.VisualLines.First().FirstDocumentLine;int probe=line.Offset+26;Point sp=CharacterPoint(input,probe);check(input.Hit(sp)==probe,"Scrolled coordinate remains exact");
   }
  }finally{editor.LayoutTransform=Transform.Identity;editor.SetFontSize(16);main.Topmost=topmost;SetCursorPos(saved.X,saved.Y);if(foreground!=IntPtr.Zero)SetForegroundWindow(foreground);}
  check(hits>500&&clicks==18&&drags==18,"Coordinate coverage "+hits+" hits / 18 clicks / 18 drags");
  editor.Text="int main(void) {\n    // return 1;\n    puts(\"int\");\n    return 0;\n}";using(var highlighter=new DocumentHighlighter(input.Document,input.SyntaxHighlighting)){check(highlighter.HighlightLine(1).Sections.Any(x=>x.Offset==0&&x.Color.Foreground!=null),"C keyword uses colored syntax section");check(highlighter.HighlightLine(2).Sections.Any(x=>x.Color.Name=="Comment"),"Comments have their own syntax color");}
  foreach(string nl in new[]{"\n","\r\n"}){editor.Text="int main(void) {"+nl+"    return 0;"+nl+"}";int start=editor.Text.IndexOf("return");input.Select(start,0);RaiseKey(main,input,Key.Tab);check(input.CaretOffset==start+4&&input.Text.Substring(start,4)=="    ","Tab caret matches inserted spaces with newline length "+nl.Length);editor.Text="int main(void) {"+nl+"    if (1) {";input.Select(input.Text.Length,0);RaiseKey(main,input,Key.Enter);check(input.Text.EndsWith(nl+"        ")&&input.CaretOffset==input.Text.Length,"Enter indentation exact with newline length "+nl.Length);}
  editor.Text=Bank.All()[0].Reference;await Task.Delay(1100);int changes=editor.InputChangeCount,states=main.DraftStateChangeCount;input.Select(10,0);int caret=input.CaretOffset;editor.RefreshView();await Task.Delay(1300);check(editor.InputChangeCount==changes&&main.DraftStateChangeCount==states&&input.CaretOffset==caret,"Highlight redraw leaves draft status, text and caret stable");
  await main.Evaluate(false);var ev=Field<Evaluation>(main,"evaluation");check(ev!=null&&ev.Score>=99.9&&ev.Cases.Count==28,"GUI compiles embedded answer and grades 100");check(Field<ComboBox>(main,"outputCases").Items.Count==28&&Field<TextBox>(main,"outputDetail").Text.Contains("实际输出"),"Main results show all 28 selectable actual outputs");var celebration=Field<Celebration>(main,"celebration");check(celebration.IsAnimating&&celebration.DurationMilliseconds==1000,"Celebration lasts 1000ms");await Task.Delay(1150);check(!celebration.IsAnimating,"Celebration finishes naturally");
  editor.Text="#include <stdio.h>\nint main(void){puts(\"WRONG\");return 0;}";await main.Evaluate(false);check(Field<Evaluation>(main,"evaluation").Score==0&&Field<TextBox>(main,"outputDetail").Text.Contains("WRONG"),"Incorrect output appears in main panel and score zero");editor.Text="int main(){???}";await main.Evaluate(false);check(Field<TextBox>(main,"outputDetail").Text.Contains("answer.c:"),"Compiler diagnostics appear in main results panel");
  editor.Text=Bank.All()[0].Reference;await main.Evaluate(false);await Task.Delay(1150);
  foreach(double dpi in new[]{96.0,144.0,192.0}){main.PreviewSize(2560*96/dpi,1600*96/dpi);await Task.Delay(180);root=(FrameworkElement)main.Content;check(Bounds(Field<Button>(main,"hint"),root).Bottom<=Bounds(Field<TextBlock>(main,"statement"),root).Top,"Requirements and hints do not overlap at "+dpi+" DPI");check(input.ActualWidth>560&&input.ActualHeight>200,"Usable editor at 2560x1600 / "+dpi+" DPI");Theme.Capture(root,Path.Combine(folder,"ver1.0.1-2560x1600-"+dpi.ToString("0")+"dpi.png"),dpi);}
 }
 static void RaiseKey(MainWindow w,EditorInput input,Key key){input.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(w),0,key){RoutedEvent=Keyboard.PreviewKeyDownEvent});}
}
